<div class="content"><section class="title"><div><span class="eyebrow">VENTAS</span><h1>GESTIÓN DE <em>PEDIDOS.</em></h1><p>Todos los pedidos generados desde el checkout de la tienda.</p></div></section><section class="panel module-panel"><div class="module-filters"><a href="<?=url('admin/pedidos')?>">TODOS</a><a href="<?=url('admin/pedidos?status=paid')?>">PAGADOS</a><a href="<?=url('admin/pedidos?status=pending')?>">PENDIENTES</a></div><div class="table-wrap"><table><thead><tr><th>PEDIDO</th><th>CLIENTE</th><th>CONTACTO</th><th>FOTOS</th><th>TOTAL</th><th>ESTADO</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><b>#UMD-<?=str_pad((string)$o['id'],4,'0',STR_PAD_LEFT)?></b><small><?=date('d/m/Y H:i',strtotime($o['created_at']))?></small></td><td><?=htmlspecialchars($o['customer_name'])?></td><td><?=htmlspecialchars($o['customer_email'])?><small><?=htmlspecialchars($o['phone']??'')?></small></td><td><?=$o['items']?></td><td><b><?=money((int)$o['total'])?></b></td><td><span class="status <?=$o['status']==='paid'?'paid':'pending'?>"><?=strtoupper($o['status'])?></span></td><td><a href="<?=url('admin/pedidos?id='.$o['id'])?>">VER →</a></td></tr><?php endforeach;?></tbody></table></div></section><?php if($selected):?><section class="panel order-detail"><div><span class="eyebrow">DETALLE</span><h2>PEDIDO #UMD-<?=str_pad((string)$selected['id'],4,'0',STR_PAD_LEFT)?></h2><p><?=htmlspecialchars($selected['customer_name'])?> · <?=htmlspecialchars($selected['customer_email'])?> · <?=htmlspecialchars($selected['rut']??'')?></p></div><form method="post" action="<?=url('admin/pedidos/estado')?>"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$selected['id']?>"><select name="status"><option value="pending" <?=$selected['status']==='pending'?'selected':''?>>Pendiente</option><option value="paid" <?=$selected['status']==='paid'?'selected':''?>>Pagado</option><option value="failed" <?=$selected['status']==='failed'?'selected':''?>>Fallido</option><option value="refunded" <?=$selected['status']==='refunded'?'selected':''?>>Reembolsado</option></select><button>ACTUALIZAR ESTADO</button></form><div class="order-products"><?php foreach($items as $i):?><article><img src="<?=media($i['preview_path'])?>"><span><b><?=htmlspecialchars($i['title'])?></b><small><?=htmlspecialchars($i['event_name'])?></small></span><strong><?=money((int)$i['unit_price'])?></strong></article><?php endforeach;?></div></section><?php endif;?></div>

